// src/services/api.js
import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:3000/api';

const api = axios.create({
  baseURL: API_URL,
  headers: {
    'Content-Type': 'application/json',
  },
  timeout: 10000, // Thêm timeout 10 giây
});

// Request interceptor
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Response interceptor với xử lý lỗi chi tiết
api.interceptors.response.use(
  (response) => response.data, // Trả về thẳng data
  (error) => {
    if (error.response) {
      // Xử lý lỗi validation từ server
      if (error.response.status === 400 && error.response.data.errors) {
        const validationErrors = error.response.data.errors;
        const errorMessages = Object.values(validationErrors).flat();
        return Promise.reject(new Error(errorMessages.join('\n')));
      }
      
      if (error.response.status === 401) {
        localStorage.removeItem('token');
        window.location.href = '/login';
      }
    }
    return Promise.reject(error);
  }
);

// API Auth với xử lý lỗi đặc biệt cho đăng ký
export const authAPI = {
  register: (userData) => {
    // Chuẩn hóa dữ liệu trước khi gửi
    const formattedData = {
      username: userData.username,
      email: userData.email,
      password: userData.password
    };
    return api.post('/auth/signup', formattedData);
  },
  
  login: (credentials) => api.post('/auth/login', {
    email: credentials.email,
    password: credentials.password
  }),
  
  logout: () => {
    localStorage.removeItem('token');
    return Promise.resolve();
  }
};

// API Products
export const productAPI = {
  getProducts: () => api.get('/products'),
  getProductDetails: (id) => api.get(`/products/${id}`),
  createProduct: (productData) => api.post('/products', productData),
  updateProduct: (id, productData) => api.put(`/products/${id}`, productData),
  deleteProduct: (id) => api.delete(`/products/${id}`)
};

// API Orders
export const orderAPI = {
  createOrder: (orderData) => api.post('/orders', orderData),
  getOrderDetails: (id) => api.get(`/orders/${id}`),
  getUserOrders: (userId) => api.get(`/orders/user/${userId}`)
};

export default api;
